CREATE TYPE "event_enum" AS ENUM (
	'planned',
	'ongoing',
	'finished',
	'cancelled'
);

CREATE TYPE "status_seat_enum" AS ENUM (
	'AVAILABLE',
	'BOOKED',
	'HOLD'
);

CREATE TABLE IF NOT EXISTS "events" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	"event_type_id" INTEGER,
	"category_id" INTEGER,
	"date" DATE,
	"start_time" TIME,
	"end_time" TIME,
	"status" EVENT_ENUM,
	"venue_id" INTEGER,
	"create_at" TIMESTAMP,
	"update_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "ward" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name_vi" VARCHAR(50) NOT NULL,
	"name_en" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "city" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name_vi" VARCHAR(50) NOT NULL,
	"name_en" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "venue" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name_vi" VARCHAR(50) NOT NULL,
	"name_en" VARCHAR(50) NOT NULL,
	"address_id" INTEGER,
	"ward_id" INTEGER,
	"city_id" INTEGER,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "street_address" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name_vi" VARCHAR(255) NOT NULL,
	"name_en" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "event_types" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "seats" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"event_id" INTEGER,
	"name" VARCHAR(255),
	"row_name" VARCHAR(5),
	"col_name" VARCHAR(5),
	"seat_code" VARCHAR(5),
	"status" STATUS_SEAT_ENUM,
	"price" DECIMAL(10,2),
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "zones" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"event_id" INTEGER,
	"name" VARCHAR(255),
	"capacity" INTEGER DEFAULT 0,
	"quantity_sold" INTEGER DEFAULT 0 CHECK(quantity_sold >= 0),
	"price_default" DECIMAL(10,2),
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "categories" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "categories" IS 'Thể loại của sự kiện';

ALTER TABLE "events"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "events"
ADD FOREIGN KEY("venue_id") REFERENCES "venue"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "zones"
ADD FOREIGN KEY("event_id") REFERENCES "events"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "seats"
ADD FOREIGN KEY("event_id") REFERENCES "events"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "events"
ADD FOREIGN KEY("event_type_id") REFERENCES "event_types"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venue"
ADD FOREIGN KEY("address_id") REFERENCES "street_address"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venue"
ADD FOREIGN KEY("ward_id") REFERENCES "ward"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venue"
ADD FOREIGN KEY("city_id") REFERENCES "city"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;